function hexToRgb(hex) {
  hex = hex.replace('#', '');
  if (hex.length === 3) hex = hex.split('').map(c => c + c).join('');
  const num = parseInt(hex, 16);
  return {
    r: ((num >> 16) & 255) / 255,
    g: ((num >> 8) & 255) / 255,
    b: (num & 255) / 255
  };
}

const COLORS = {
  neutralDark: hexToRgb('#132f2c'),
  neutralWhite: hexToRgb('#ffffff'),
  brandPrimary: hexToRgb('#183c38'),
  brandGold: hexToRgb('#bb893a'),
  brandBrown: hexToRgb('#845e41'),
  surfaceBg: hexToRgb('#fcfbf8'),
  darkPreview: hexToRgb('#1d2026') // Dark contrast background matching Kaayo
};

function createPaintStyles() {
  const stylesToCreate = [
    { name: 'Maligai / Neutral / Dark', color: COLORS.neutralDark },
    { name: 'Maligai / Neutral / White', color: COLORS.neutralWhite },
    { name: 'Maligai / Brand / Primary Teal', color: COLORS.brandPrimary },
    { name: 'Maligai / Brand / Accent Gold', color: COLORS.brandGold },
    { name: 'Maligai / Brand / Accent Brown', color: COLORS.brandBrown },
    { name: 'Maligai / Surface / Background', color: COLORS.surfaceBg },
  ];

  const localStyles = figma.getLocalPaintStyles();
  for (const item of stylesToCreate) {
    let existing = localStyles.find(s => s.name === item.name);
    if (!existing) {
      existing = figma.createPaintStyle();
      existing.name = item.name;
      existing.paints = [{ type: 'SOLID', color: item.color }];
    }
  }
}

function createComponentFromSvg(svgStr, variantName) {
  const frame = figma.createNodeFromSvg(svgStr);
  const comp = figma.createComponent();
  comp.name = variantName;
  comp.resize(frame.width, frame.height);
  comp.fills = frame.fills;
  comp.clipsContent = false;

  while (frame.children.length > 0) {
    comp.appendChild(frame.children[0]);
  }
  frame.remove();
  return comp;
}

function createAssetFrameFromSvg(svgStr, frameName) {
  const frame = figma.createNodeFromSvg(svgStr);
  frame.name = frameName;
  frame.clipsContent = false;
  return frame;
}

async function main() {
  console.log("Starting Maligai Manager Logo update from SVGs...");

  // 1. Create paint styles
  createPaintStyles();

  // 2. Find target location
  // We locate the existing section so we can place our new master section cleanly alongside it WITHOUT touching existing elements
  const existingSection = figma.currentPage.findOne(n => 
    n.type === 'SECTION' && (n.name.includes("MALIGAI MANAGER") || n.id === "69326:2")
  );

  let targetX = 35600;
  let targetY = 900;

  if (existingSection) {
    targetX = existingSection.x + existingSection.width + 120;
    targetY = existingSection.y;
  }

  // 3. Create Main Section: "MALIGAI MANAGER — LOGO MASTER COMPONENTS" (LEMNISCATE style)
  const masterSection = figma.createSection();
  masterSection.name = "MALIGAI MANAGER — LOGO MASTER COMPONENTS";
  masterSection.x = targetX;
  masterSection.y = targetY;
  masterSection.fills = [{ type: 'SOLID', color: hexToRgb('#e4ecf8') }];

  // Section title
  await figma.loadFontAsync({ family: "Inter", style: "Bold" });
  await figma.loadFontAsync({ family: "Inter", style: "Regular" });

  const title = figma.createText();
  title.characters = "MALIGAI MANAGER — LOGO MASTER COMPONENTS";
  title.fontSize = 24;
  title.fontName = { family: "Inter", style: "Bold" };
  title.fills = [{ type: 'SOLID', color: COLORS.neutralDark }];
  title.x = 40;
  title.y = 40;
  masterSection.appendChild(title);

  const categories = [
    { key: 'horizontal', name: 'Maligai Manager / Logo / Horizontal' },
    { key: 'vertical', name: 'Maligai Manager / Logo / Vertical' },
    { key: 'symbol', name: 'Maligai Manager / Logo / Symbol' },
    { key: 'wordmark', name: 'Maligai Manager / Logo / Wordmark' }
  ];

  let currentSetY = 100;
  const createdSets = [];

  for (const cat of categories) {
    const svgsForCat = SVGS[cat.key];
    const compDefault = createComponentFromSvg(svgsForCat.default, "Colour=Default");
    const compDark = createComponentFromSvg(svgsForCat.neutral_dark, "Colour=Neutral Dark");
    const compWhite = createComponentFromSvg(svgsForCat.neutral_white, "Colour=Neutral White");
    const compFilled = createComponentFromSvg(svgsForCat.filled, "Colour=Filled");

    const comps = [compDefault, compDark, compWhite, compFilled];

    let currX = 40;
    let maxHeight = 0;
    for (const c of comps) {
      c.x = currX;
      c.y = 40;
      currX += c.width + 40;
      if (c.height > maxHeight) maxHeight = c.height;
    }

    const compSet = figma.combineAsVariants(comps, masterSection);
    compSet.name = cat.name;
    compSet.x = 40;
    compSet.y = currentSetY;
    compSet.fills = [{ type: 'SOLID', color: hexToRgb('#ffffff') }];
    compSet.cornerRadius = 8;
    compSet.paddingLeft = 40;
    compSet.paddingRight = 40;
    compSet.paddingTop = 40;
    compSet.paddingBottom = 40;

    createdSets.push(compSet);
    currentSetY += compSet.height + 60;
  }

  masterSection.resize(1300, currentSetY + 40);

  // 4. Create Section: "For dev assets" (Kaayo style 73973:596)
  const devAssetsSection = figma.createSection();
  devAssetsSection.name = "For dev assets";
  devAssetsSection.x = targetX + masterSection.width + 120;
  devAssetsSection.y = targetY;
  devAssetsSection.fills = [{ type: 'SOLID', color: hexToRgb('#ffffff') }];

  const devTitle = figma.createText();
  devTitle.characters = "For dev assets";
  devTitle.fontSize = 24;
  devTitle.fontName = { family: "Inter", style: "Bold" };
  devTitle.fills = [{ type: 'SOLID', color: COLORS.neutralDark }];
  devTitle.x = 40;
  devTitle.y = 40;
  devAssetsSection.appendChild(devTitle);

  // Dark background strip for white assets (matching Kaayo's Rectangle 1)
  const darkBg = figma.createRectangle();
  darkBg.name = "Rectangle 1";
  darkBg.fills = [{ type: 'SOLID', color: COLORS.darkPreview }];
  darkBg.cornerRadius = 8;
  devAssetsSection.appendChild(darkBg);

  const assetRows = [
    { prefix: 'symbol', cat: 'symbol' },
    { prefix: 'Vertical', cat: 'vertical' },
    { prefix: 'Word', cat: 'wordmark' },
    { prefix: 'Horizontal', cat: 'horizontal' },
  ];

  const colX = [60, 320, 580, 840]; // White, Black, Filled, Default
  let assetY = 120;

  for (const row of assetRows) {
    const svgsForCat = SVGS[row.cat];

    const fWhite = createAssetFrameFromSvg(svgsForCat.neutral_white, row.prefix + "_white");
    const fBlack = createAssetFrameFromSvg(svgsForCat.neutral_dark, row.prefix + "_black");
    const fFilled = createAssetFrameFromSvg(svgsForCat.filled, row.prefix + "_filled");
    const fDefault = createAssetFrameFromSvg(svgsForCat.default, row.prefix);

    const frames = [fWhite, fBlack, fFilled, fDefault];

    let rowMaxH = 0;
    for (let i = 0; i < 4; i++) {
      const fr = frames[i];
      fr.x = colX[i];
      fr.y = assetY;
      devAssetsSection.appendChild(fr);
      if (fr.height > rowMaxH) rowMaxH = fr.height;
    }

    assetY += Math.max(rowMaxH, 80) + 60;
  }

  darkBg.x = 40;
  darkBg.y = 100;
  darkBg.resize(250, assetY - 100);

  devAssetsSection.resize(1160, assetY + 40);

  // Zoom into the created sections
  figma.viewport.scrollAndZoomIntoView([masterSection, devAssetsSection]);

  figma.notify("🎉 Maligai Manager Logo Masters & Dev Assets created cleanly from your SVGs!");
  figma.closePlugin();
}

main().catch(err => {
  console.error(err);
  figma.notify("❌ Error: " + err.message);
  figma.closePlugin();
});
